/**
 * EAN-13 helpers. Barcodes generated by the app use the "2" prefix, which
 * GS1 reserves for in-store / restricted circulation numbers, so they never
 * collide with manufacturer barcodes.
 */

export function ean13CheckDigit(first12: string): number {
  if (!/^\d{12}$/.test(first12)) {
    throw new Error("EAN-13 check digit needs exactly 12 digits");
  }
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    sum += Number(first12[i]) * (i % 2 === 0 ? 1 : 3);
  }
  return (10 - (sum % 10)) % 10;
}

export function isValidEan13(code: string): boolean {
  return /^\d{13}$/.test(code) && ean13CheckDigit(code.slice(0, 12)) === Number(code[12]);
}

export function generateInternalEan13(random: () => number = Math.random): string {
  let body = "2";
  for (let i = 0; i < 11; i++) body += Math.floor(random() * 10).toString();
  return body + ean13CheckDigit(body);
}

/** Pick the most appropriate symbology for rendering a stored barcode. */
export function barcodeSymbology(code: string): "ean13" | "code128" {
  return isValidEan13(code) ? "ean13" : "code128";
}
